<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ShieldCheck, Sparkles, UserRound, Square, PencilLine } from 'lucide-vue-next';
import SpecialWorkspace from './SpecialWorkspace.vue';
import { assignments, campusProject } from './campus-handoff';
import type { CampusTaskStore, SpecialNote, CheckResult } from './task-store';
import type { ScenarioId, ScenarioRuns } from './special-engine';
const props = defineProps<{ store: CampusTaskStore; runs: ScenarioRuns; busy: boolean; busyId: ScenarioId | null; running: boolean }>();
const emit = defineEmits<{ generate: []; advance: [id: ScenarioId, step: number]; reset: [id: ScenarioId, parameter?: string]; report: []; cancel: []; note: [id: ScenarioId, value: SpecialNote]; manual: [id: ScenarioId, result: CheckResult] }>();
const selected = ref<ScenarioId>('duplicate');
const assignment = computed(()=>assignments.find(a=>a.id===selected.value)!);
const note = ref(''), checkpoint = ref('');
function syncDraft() { note.value=props.store.specialNotes[selected.value]?.note || '';checkpoint.value=props.store.specialNotes[selected.value]?.checkpoint || ''; }
watch(selected,syncDraft); syncDraft();
</script>
<template><div class="section-intro"><div><span class="eyebrow">BACKEND ASSIGNMENT / BUSINESS GUARDS</span><h1>工程师指定风险，你来核验边界。</h1><p>固定验收标准保持不变，可调整场景参数和补充人工检查；每一步都由你手动触发。</p></div><button v-if="running" class="secondary" @click="emit('cancel')"><Square :size="14"/>取消当前专项操作</button></div><section class="panel engineer-assignment"><div class="panel-heading"><h2><UserRound :size="18"/>后端工程师专项指派</h2><button class="primary" :disabled="busy || !!store.specialGeneratedAt" @click="emit('generate')"><Sparkles :size="15"/>{{store.specialGeneratedAt?'专项用例已生成':'生成专项用例'}}</button></div><div class="engineer-message"><span class="avatar">陈</span><div><b>{{campusProject.backend}}</b><p>请重点验证预约写入、同一时段资源与班级权限。以下为本轮验收要求，请保留过程与断言证据。</p><small>关联交付 {{store.handoffId}} · 指派 4 项</small></div></div><div class="assignment-grid"><article v-for="item in assignments" :key="item.id"><span class="eyebrow">{{item.endpointId}}</span><h3><ShieldCheck :size="16"/>{{item.title}}</h3><p>{{item.risk}}</p><div><b>验收标准</b>{{item.standard}}</div></article></div></section><div v-if="!store.specialGeneratedAt" class="panel empty-state special-wait"><ShieldCheck :size="37"/><h3>等待手动生成专项用例</h3><p>生成后出现对应场景，不会自动准备条件或执行请求。</p></div><template v-else><SpecialWorkspace class="campus-special-workspace" campus :runs="runs" :busy="busy" :busy-id="busyId" @advance="(id,step)=>emit('advance',id,step)" @reset="(id,parameter)=>emit('reset',id,parameter)" @report="emit('report')" @select="id=>selected=id"/><section class="panel special-case-notes"><div class="panel-heading"><h3><PencilLine :size="17"/>{{assignment.title}} · 用例补充</h3><span>原始指派标准不可修改</span></div><div class="special-note-form"><label>执行备注<textarea v-model="note" aria-label="专项执行备注" rows="2" maxlength="1000" :disabled="busy"/></label><label>补充人工检查点<textarea v-model="checkpoint" aria-label="专项补充检查点" rows="2" maxlength="1000" :disabled="busy"/></label><div><button class="secondary" :disabled="busy" @click="emit('note',selected,{note,checkpoint,result:'pending'})">保存专项用例补充</button><template v-if="store.specialNotes[selected]?.checkpoint"><button class="secondary" :disabled="busy || runs[selected].step!==3" @click="emit('manual',selected,'passed')">确认专项补充检查通过</button><button class="secondary" :disabled="busy || runs[selected].step!==3" @click="emit('manual',selected,'issue')">专项补充检查需整改</button><span class="badge">{{store.specialNotes[selected]?.result==='passed'?'通过':store.specialNotes[selected]?.result==='issue'?'需整改':'待人工确认'}}</span></template></div></div></section></template></template>
